package com.wheelwright.evidence.v2;

import com.wheelwright.evidence.db.SqliteEvidenceStore;
import com.wheelwright.evidence.v2.portfolio.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioJson.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioRepository.*;

/** Principal-approved qualified reconciliation, synthetic source scope; no broker lifecycle claim. */
class PortfolioContinuityTest {
 @TempDir Path directory;SqliteEvidenceStore db;PortfolioRepository repo;AccountDirectory accounts;String account,bytes;PortfolioSources sources;
 @BeforeEach void setup()throws Exception{db=new SqliteEvidenceStore(directory.resolve("continuity.db").toString());repo=new PortfolioRepository(db,JSON);accounts=new AccountDirectory(db,"");account=accounts.bind("test","TASTYTRADE","TEST1234");bytes=Files.readString(Path.of("src/test/resources/tastytrade/xle-api.json")).replace("TTTEST01","TEST1234");sources=new PortfolioSources(repo,JSON,accounts);observe(bytes);}
 @AfterEach void close()throws Exception{db.close();}
 void observe(String value)throws Exception{var client=mock(TastytradeClient.class);when(client.holdings("TEST1234")).thenReturn(value.getBytes(StandardCharsets.UTF_8));when(client.settledCashBalance("TEST1234")).thenThrow(new IllegalStateException("Synthetic fixture supplies no cash history"));new PositionAcquisition(db,accounts,new PositionReadService(db,JSON),client).acquire(account,UUID.randomUUID().toString());sources.refresh(Set.of(account));}
 List<Document> positions()throws Exception{return repo.list(Kind.POSITION,Set.of(account));}
 Document construction(Document p)throws Exception{return repo.get(p.value().at("/currentConstruction/href").asText()).orElseThrow();}
 Set<String> ids(List<Document> positions){var set=new TreeSet<String>();positions.forEach(p->set.add(p.uri()));return set;}
 @Test void currentHoldingsCutUsesReceiptInstantsRatherThanFractionSpelling()throws Exception{
  observe(bytes);var snapshots=new PortfolioSnapshots(repo).retained(Set.of(account));assertThat(snapshots).hasSize(2);String expected=snapshots.getFirst().snapshotId();for(var snapshot:snapshots){String receipt=snapshot.evidenceDate()+"T17:59:00."+(snapshot.snapshotId().equals(expected)?"900001":"9")+"Z";var value=(com.fasterxml.jackson.databind.node.ObjectNode)JSON.valueToTree(snapshot);value.put("recordedAt",receipt);try(var tx=repo.connection();var q=tx.prepareStatement("UPDATE account_position_snapshot SET recorded_at=?,payload_json=? WHERE account=? AND snapshot_id=?")){q.setString(1,receipt);q.setString(2,JSON.writeValueAsString(value));q.setString(3,account);q.setString(4,snapshot.snapshotId());q.executeUpdate();}}assertThat(new PortfolioSnapshots(repo).current(account).orElseThrow().snapshotId()).isEqualTo(expected);
 }
 @Test void identicalObservationsReuseGuidWithoutProvingOccurrenceOrOpening()throws Exception{
  var before=positions();var originals=new HashMap<String,Document>();for(var p:before)originals.put(p.uri(),construction(p));observe(bytes);assertThat(ids(positions())).isEqualTo(ids(before));assertThat(new PortfolioSnapshots(repo).retained(Set.of(account))).hasSize(2);
  for(var p:positions()){assertThat(p.value().path("state").asText()).isEqualTo("UNRESOLVED");assertThat(p.value().at("/stateEvidence/status").asText()).isEqualTo("UNRESOLVED");assertThat(p.value().at("/stateEvidence/establishedAt").isNull()).isTrue();assertThat(p.value().at("/evaluation/timeline/openedAt").isNull()).isTrue();assertThat(p.value().at("/evaluation/timeline/originalDays/value").isNull()).isTrue();assertThat(p.value().path("warnings").toString()).contains("ASSOCIATION_UNRESOLVED");assertThat(construction(p).value().at("/predecessor/href").asText()).isEqualTo(originals.get(p.uri()).uri());assertThat(repo.get(originals.get(p.uri()).uri()).orElseThrow().value()).isEqualTo(originals.get(p.uri()).value());}
  var second=new HashMap<String,String>();for(var p:positions())second.put(p.uri(),construction(p).uri());observe(bytes);assertThat(ids(positions())).isEqualTo(ids(before));for(var p:positions())assertThat(construction(p).value().at("/predecessor/href").asText()).isEqualTo(second.get(p.uri()));
 }
 @Test void ambiguousMatchesRemainSeparateAndDoNotSpawnAnotherGuess()throws Exception{
  var original=positions().getFirst();var old=construction(original);String pid=UUID.randomUUID().toString(),puri="/v2/positions/"+pid,cid=UUID.randomUUID().toString(),curi="/v2/constructions/"+cid;var c=old.value().deepCopy();c.put("id",cid);c.set("self",link(curi));c.set("position",link(puri));var p=original.value().deepCopy();p.put("id",pid);p.set("self",link(puri));p.set("audit",link(puri+"/audit"));p.set("currentConstruction",link(curi));try(var tx=repo.connection()){repo.put(tx,new Document(Kind.CONSTRUCTION,curi,account,c,original.snapshot(),original.sourceKey()));repo.put(tx,new Document(Kind.POSITION,puri,account,p,original.snapshot(),original.sourceKey()));}
  var before=ids(positions());observe(bytes);assertThat(ids(positions())).isEqualTo(before);assertThat(construction(repo.get(original.uri()).orElseThrow()).uri()).isEqualTo(old.uri());assertThat(construction(repo.get(puri).orElseThrow()).uri()).isEqualTo(curi);assertThat(repo.list(Kind.HOLDING,Set.of(account))).hasSize(8);assertThat(repo.list(Kind.HOLDING,Set.of(account)).stream().filter(h->!h.snapshot().equals(original.snapshot())).toList()).allSatisfy(h->assertThat(h.value().path("warnings").toString()).contains("ASSOCIATION_UNRESOLVED"));
 }
 @Test void incompatibleQuantityDoesNotInventSplitOrNewOccurrence()throws Exception{
  var before=positions();var raw=JSON.readTree(bytes);var changed=(com.fasterxml.jackson.databind.node.ObjectNode)raw.at("/data/items/0");changed.put("quantity",new java.math.BigDecimal(changed.path("quantity").asText()).add(java.math.BigDecimal.ONE).toPlainString());observe(JSON.writeValueAsString(raw));assertThat(ids(positions())).isEqualTo(ids(before));assertThat(new PortfolioSnapshots(repo).retained(Set.of(account))).hasSize(2);
 }
 @Test void conflictingKnownContractTermsWithholdAssociationRatherThanInventingOccurrence()throws Exception{
  var original=positions().stream().filter(p->{try{return leaves(construction(p).value().path("composition")).getFirst().path("kind").asText().equals("OPTION");}catch(Exception e){throw new RuntimeException(e);}}).findFirst().orElseThrow();var old=construction(original);var c=old.value().deepCopy();String cid=UUID.randomUUID().toString(),curi="/v2/constructions/"+cid;c.put("id",cid).put("changeKind","EVIDENCE_REINTERPRETATION").put("predecessorStatus","KNOWN");c.set("self",link(curi));c.set("predecessor",old.value().path("self"));((com.fasterxml.jackson.databind.node.ObjectNode)leaves(c.path("composition")).getFirst().path("terms")).put("strike","777");var p=original.value().deepCopy();p.set("currentConstruction",link(curi));try(var tx=repo.connection()){repo.put(tx,new Document(Kind.CONSTRUCTION,curi,account,c,original.snapshot(),original.sourceKey()));repo.put(tx,new Document(Kind.POSITION,original.uri(),account,p,original.snapshot(),original.sourceKey()));}var before=ids(positions());observe(bytes);assertThat(ids(positions())).isEqualTo(before);assertThat(construction(repo.get(original.uri()).orElseThrow()).uri()).isEqualTo(curi);
 }
 @Test void establishedOpenScopeIsNotSilentlyReinterpretedAsUnresolved()throws Exception{
  var original=positions().getFirst();var p=original.value().deepCopy();p.put("state","OPEN");try(var tx=repo.connection()){repo.put(tx,new Document(Kind.POSITION,original.uri(),account,p,original.snapshot(),original.sourceKey()));}var before=ids(positions());observe(bytes);assertThat(ids(positions())).isEqualTo(before);assertThat(repo.get(original.uri()).orElseThrow().value()).isEqualTo(p);
 }
 @Test void overlappingPackageScopeCannotInventSplitOrRecombination()throws Exception{
  var existing=positions();var original=existing.get(0);var old=construction(original);var other=construction(existing.get(1));String pid=UUID.randomUUID().toString(),puri="/v2/positions/"+pid,cid=UUID.randomUUID().toString(),curi="/v2/constructions/"+cid;var c=old.value().deepCopy();c.put("id",cid);c.set("self",link(curi));c.set("position",link(puri));((com.fasterxml.jackson.databind.node.ArrayNode)c.at("/composition/children")).add(leaves(other.value().path("composition")).getFirst().deepCopy());var p=original.value().deepCopy();p.put("id",pid);p.set("self",link(puri));p.set("audit",link(puri+"/audit"));p.set("currentConstruction",link(curi));try(var tx=repo.connection()){repo.put(tx,new Document(Kind.CONSTRUCTION,curi,account,c,original.snapshot(),"synthetic-overlap"));repo.put(tx,new Document(Kind.POSITION,puri,account,p,original.snapshot(),"synthetic-overlap"));}var before=ids(positions());observe(bytes);assertThat(ids(positions())).isEqualTo(before);assertThat(construction(repo.get(original.uri()).orElseThrow()).uri()).isEqualTo(old.uri());assertThat(construction(repo.get(existing.get(1).uri()).orElseThrow()).uri()).isEqualTo(other.uri());
 }
 @Test void retainingGuidDoesNotEraseRecordedHistoryOrPromoteItsCompleteness()throws Exception{
  var original=positions().getFirst();var old=construction(original);var comparison=PortfolioEconomicHistory.compare(old.value(),old.value(),obj().put("historyStatus","UNKNOWN"),Instant.now());var p=original.value().deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)p.path("evaluation")).set("economicComparison",comparison);try(var tx=repo.connection()){repo.put(tx,new Document(Kind.POSITION,original.uri(),account,p,original.snapshot(),original.sourceKey()));}observe(bytes);var retained=repo.get(original.uri()).orElseThrow().value().at("/evaluation/economicComparison");assertThat(retained).isEqualTo(comparison);assertThat(retained.at("/cumulative/historyStatus").asText()).isEqualTo("UNKNOWN");assertThat(retained.at("/cumulative/netDocumentedOptionCashFlow/value").isNull()).isTrue();
 }
 @Test void scopedClosureIsTerminalAndLaterObservedExposureUsesNewGuid()throws Exception{
  var original=positions().getFirst();var old=construction(original);String cid=UUID.randomUUID().toString(),curi="/v2/constructions/"+cid;var terminal=old.value().deepCopy();terminal.put("id",cid).put("changeKind","EXPOSURE_CHANGE").put("predecessorStatus","KNOWN");terminal.set("self",link(curi));terminal.set("predecessor",old.value().path("self"));((com.fasterxml.jackson.databind.node.ObjectNode)terminal.path("composition")).set("children",array());var closed=original.value().deepCopy();closed.put("state","CLOSED");closed.set("currentConstruction",link(curi));
  // Explicit synthetic scoped closure evidence, independent of the holdings snapshots.
  String artifact=UUID.randomUUID().toString(),at=Instant.now().toString();byte[] facts=("{\"synthetic\":true,\"position\":\""+original.uri()+"\",\"completeClosure\":true,\"at\":\""+at+"\"}").getBytes(StandardCharsets.UTF_8);var evidence=source(account,artifact,"/completeClosure",at.substring(0,10),at,"SYNTHETIC_SCOPED_CLOSURE");var state=(com.fasterxml.jackson.databind.node.ObjectNode)closed.path("stateEvidence");state.put("status","ESTABLISHED").put("completeness","SCOPED_ACCEPTED").put("establishedAt",at);state.set("evidence",array().add(evidence));
  try(var tx=repo.connection()){try(var q=tx.prepareStatement("INSERT INTO brokerage_artifact VALUES (?,?,?,?,?,?,?)")){q.setString(1,account);q.setString(2,artifact);q.setString(3,BrokerageArtifacts.sha(facts));q.setString(4,"application/json");q.setInt(5,facts.length);q.setBytes(6,facts);q.setString(7,at);q.executeUpdate();}repo.put(tx,new Document(Kind.CONSTRUCTION,curi,account,terminal,original.snapshot(),original.sourceKey()));repo.put(tx,new Document(Kind.POSITION,original.uri(),account,closed,original.snapshot(),original.sourceKey()));assertThatThrownBy(()->repo.put(tx,original)).hasMessageContaining("terminal");}
  var before=positions();observe(bytes);assertThat(positions()).hasSize(before.size()+1);assertThat(repo.get(original.uri()).orElseThrow().value()).isEqualTo(closed);var reopened=positions().stream().filter(p->!ids(before).contains(p.uri())).findFirst().orElseThrow();assertThat(reopened.value().path("sourceIdentifiers")).isEqualTo(original.value().path("sourceIdentifiers"));assertThat(reopened.value().path("state").asText()).isEqualTo("UNRESOLVED");assertThat(reopened.value().at("/evaluation/timeline/openedAt").isNull()).isTrue();assertThat(construction(reopened).value().path("predecessor").isNull()).isTrue();
 }
}
